import {escapeHtml as e, icon, shapeIcon, number} from './ui.js';
import {formatOccurrence} from './data-engine.js';

export function reportCard(r) {
  const id=r.report_id.replace('nuforc-','');
  const location=[r.city,r.state_name].filter(Boolean).join(', ') || r.country_name;
  return `<article class="report-card"><div class="report-card-top"><span class="report-shape">${shapeIcon(r.shape_key)}${e(r.shape_name)}</span><span class="report-id">REPORT #${e(id)}</span></div><h3>${e(r.city ? `${r.shape_name} reported in ${r.city}` : `${r.shape_name} reported in ${r.state_name || r.country_name}`)}</h3><div class="report-card-meta"><span>${icon('pin')}${e(location)}</span><span>${icon('calendar')}${e(formatOccurrence(r))}</span></div><p class="report-summary">${e(r.summary || 'No summary was provided in this source record.')}</p><div class="report-card-bottom"><span>${icon(r.media_available===true?'image':'file')}${r.media_available===true?'Media indicated by source':'Source summary'}</span><button class="read-story" data-report="${e(r.report_id)}" aria-label="Read report ${e(id)}">Read report <span aria-hidden="true">→</span></button></div></article>`;
}

export function reportDetail(r) {
  const location=[r.city,r.state_name,r.country_name].filter(Boolean).join(', ');
  const flags=(r.quality_flags || []).map(flag=>`<span>${e(flag.replaceAll('_',' '))}</span>`).join('');
  const explanation=r.explanation_category ? `${r.explanation_category}${r.explanation_certainty==='possible_source_label'?' · possible source label':' · source label, certainty unspecified'}` : 'Not provided';
  return `<div class="detail-header"><div><span class="report-shape">${shapeIcon(r.shape_key)}${e(r.shape_name)}</span><span class="report-id">REPORT #${e(r.report_id.replace('nuforc-',''))}</span></div><button class="icon-button" data-action="close-report" aria-label="Close report">×</button></div><div class="detail-body"><div class="eyebrow">FROM THE SOURCE REPORT</div><h2 id="detail-title" style="margin-top:9px">${e(r.city ? `A reported sighting in ${r.city}` : `A reported sighting in ${r.state_name || r.country_name}`)}</h2><dl class="detail-grid"><div><dt>Reported occurrence</dt><dd>${e(formatOccurrence(r,true))}</dd></div><div><dt>Reported location</dt><dd>${e(location)}</dd></div><div><dt>Shape</dt><dd>${e(r.shape_name)}</dd></div><div><dt>Media indicator</dt><dd>${r.media_available===true?'Yes, indicated by the source':r.media_available===false?'No, according to the source':'Not provided'}</dd></div><div><dt>Source explanation</dt><dd>${e(explanation)}</dd></div><div><dt>Time basis</dt><dd>Recorded local time; timezone not supplied</dd></div></dl><div class="eyebrow" style="margin-bottom:10px">SOURCE SUMMARY</div><p class="detail-summary">${e(r.summary || 'No summary was provided in this dataset.')}</p>${flags?`<div class="detail-flags">${flags}</div>`:''}<p class="detail-note">This is the summary supplied in the dataset. It is a self-reported account, not a verified extraterrestrial event. A missing explanation or media field does not establish what happened.</p><div class="detail-actions">${r.source_url?`<a class="primary-button" href="${e(r.source_url)}" target="_blank" rel="noopener noreferrer">Read the original NUFORC report <span aria-hidden="true">↗</span></a>`:''}<button class="secondary-button" data-action="close-report">Back to the observatory</button></div></div>`;
}

export function aboutContent(manifest, quality) {
  const source=manifest.source || {};
  return `<article class="about-intro"><div><div class="eyebrow" style="margin-bottom:9px">CURIOUS BY NATURE. CAREFUL WITH DATA.</div><h3>From a Fabric export to something you can explore.</h3><p>This observatory explores the group’s US-only cleaned export of NUFORC sighting reports. The data was cleaned, modelled and exported through Microsoft Fabric for a Vlerick Modern Data Platforms group project. The graphics use real counts from that snapshot.</p></div><img src="./assets/mascot.png" width="170" height="130" alt=""></article>
  <div class="quality-grid"><div class="quality-card"><strong>${number(quality.raw_rows)}</strong><span>Fabric export rows</span><p>The supplied final JSON is fingerprinted before adaptation.</p></div><div class="quality-card"><strong>${number(quality.clean_reports)}</strong><span>distinct source reports</span><p>All supplied report IDs retained. Upstream removals are described in the project cleaning notes.</p></div><div class="quality-card"><strong>${number(quality.valid_time_reports)}</strong><span>usable occurrence dates</span><p>${number(quality.reports_excluded_from_time_charts)} pre-1900 dates remain flagged and excluded from time charts.</p></div><div class="quality-card"><strong>${quality.us_state_mapping_coverage_pct}%</strong><span>US map coverage</span><p>${number(quality.reports_mapped_to_us_states)} of ${number(quality.us_reports)} US-labelled reports match the map.</p></div></div>
  <div class="about-grid"><article class="panel about-panel"><h3>${icon('database')}The data journey</h3><p>A small, traceable lifecycle: preserve the original, clean carefully, then prepare the results for exploration.</p><div class="lifecycle"><div class="lifecycle-step"><span>01 · BRONZE</span><strong>${number(quality.raw_rows)}</strong><p>Fabric JSON export<br>Source hash retained</p></div><div class="lifecycle-step"><span>02 · SILVER</span><strong>${number(quality.clean_reports)}</strong><p>Clean reports<br>Quality flags retained</p></div><div class="lifecycle-step"><span>03 · GOLD</span><strong>4</strong><p>Dimensions<br>Reconciled summaries</p></div></div><p>The fact table represents reports, not independently verified events. Country, state, shape and date dimensions support the charts. App files are exported snapshots, not a live connection to Fabric.</p></article>
  <article class="panel about-panel"><h3>${icon('sliders')}What we cleaned</h3><div class="quality-row"><span>Empty records removed</span><strong>${number(quality.empty_records_removed)}</strong></div><div class="quality-row"><span>Duplicate copies removed</span><strong>${number(quality.duplicate_copies_removed)}</strong></div><div class="quality-row"><span>Records excluded from time charts</span><strong>${number(quality.reports_excluded_from_time_charts)}</strong></div><div class="quality-row"><span>US records outside the state map</span><strong>${number(quality.us_reports_not_mapped)}</strong></div><div class="quality-row"><span>Reports without a city</span><strong>${number(quality.reports_without_city)}</strong></div><div class="quality-row"><span>Shapes not provided</span><strong>${number(quality.reports_with_shape_not_provided)}</strong></div><p style="margin-top:14px">These figures describe the full cleaned sample. Missing values are preserved; they are not filled with guesses.</p></article>
  <article class="panel about-panel"><h3>${icon('info')}Read the patterns with care</h3><ul><li><strong>Reports are observations.</strong> They do not establish an extraterrestrial explanation.</li><li><strong>This is a selected sample.</strong> Its scraping and selection method is undocumented. It does not represent the complete NUFORC archive.</li><li><strong>Time means reported occurrence.</strong> Occurrence dates and reporting dates are kept separately. Hours are local wall-clock values; timezones are not supplied.</li><li><strong>Counts are not rates.</strong> State shading does not adjust for population or reporting behaviour.</li><li><strong>One event may have several reports.</strong> Different source IDs are kept as separate reports.</li><li><strong>Blank is not a conclusion.</strong> No explanation or media label does not mean an event is inexplicable or lacks evidence.</li></ul><div class="about-note">Mixed date formats were resolved by original NUFORC report ID against a pinned date reference. ${number(quality.reports_excluded_from_time_charts)} pre-1900 reports remain in the dataset; ${number(quality.us_reports_not_mapped)} territory reports are outside the 50-state-plus-DC map.</div></article>
  <article class="panel about-panel"><h3>${icon('file')}Sources & snapshot</h3><dl class="source-meta"><dt>Original publisher</dt><dd><a href="https://nuforc.org/" target="_blank" rel="noopener noreferrer">National UFO Reporting Center ↗</a></dd><dt>Fabric source</dt><dd><a href="${e(source.fabric_url)}" target="_blank" rel="noopener noreferrer">dbo.UFO_Sighting ↗</a></dd><dt>Supplied export</dt><dd>${e(source.raw_file)}</dd><dt>Dataset version</dt><dd>${e(source.dataset_version || 1)} · updated ${e((source.dataset_updated_at || '').slice(0,10))}</dd><dt>Valid occurrences</dt><dd>${e(quality.earliest_valid_occurrence.slice(0,10))} to ${e(quality.latest_valid_occurrence.slice(0,10))}</dd><dt>Map boundaries</dt><dd><a href="https://www.census.gov/geographies/mapping-files/time-series/geo/cartographic-boundary.html" target="_blank" rel="noopener noreferrer">US Census Bureau · 2024 ↗</a></dd><dt>Map scope</dt><dd>50 US states + Washington, DC</dd><dt>Prepared for</dt><dd>Vlerick · Modern Data Platforms</dd></dl><p style="font-size:10px;margin-bottom:6px">Fabric export fingerprint · SHA-256</p><div class="source-hash">${e(source.raw_sha256 || '')}</div><details class="about-disclosure"><summary>Reuse and AI disclosure</summary><p>The group supplied this Fabric export and its cleaning notes. NUFORC has separate <a href="https://nuforc.org/terms/" target="_blank" rel="noopener noreferrer">reuse terms</a>; the repository does not assert a new licence over NUFORC data. Codex assisted with code and documentation, and image generation created the decorative mascot and scenery. No model guessed missing dates or places, or classified reports as true.</p></details></article></div>`;
}
